// Obtener los resultados de la validación del input del nodo.
const inputData = $input.first().json;

// Inicializar la estructura de la respuesta.
const response = {
  success: false,
  overallStatus: 'failed',
  message: '',
  details: {}
};

// Contadores para determinar el estado general.
let validCount = 0;
let totalCount = 0;

// --- 1. Procesar Ad Account ID ---
if (inputData.adAccountResult) {
  totalCount++;
  const res = inputData.adAccountResult;
  response.details.adAccountId = {
    valid: res.valid,
    message: res.valid ? "Cuenta publicitaria válida y activa" : (res.error ? `Error: ${res.error}` : "La cuenta publicitaria no es válida"),
    accountId: res.id,
    accountName: res.name || null
  };
  if (!res.valid && res.error) {
    response.details.adAccountId.error = res.error;
  }
  if (res.additionalInfo) {
    response.details.adAccountId.additionalInfo = res.additionalInfo;
  }
  if (res.valid) validCount++;
}

// --- 2. Procesar Page ID ---
if (inputData.pageResult) {
  totalCount++;
  const res = inputData.pageResult;
  response.details.pageId = {
    valid: res.valid,
    message: res.valid ? "Página de Facebook válida y accesible" : (res.error ? `Error: ${res.error}` : "La página de Facebook no es válida"),
    pageId: res.id,
    pageName: res.name || null
  };
  if (!res.valid && res.error) {
    response.details.pageId.error = res.error;
  }
  if (res.additionalInfo) {
    response.details.pageId.additionalInfo = res.additionalInfo;
  }
  if (res.valid) validCount++;
}

// --- 3. Procesar Instagram Account ID (si existe) ---
if (inputData.instagramAccountResult) {
  totalCount++;
  const res = inputData.instagramAccountResult;
  response.details.instagramAccountId = {
    valid: res.valid,
    message: res.valid ? "Cuenta de Instagram vinculada y activa" : (res.error ? `Error: ${res.error}` : "La cuenta de Instagram no es válida"),
    accountId: res.id,
    accountName: res.name || null
  };
  if (!res.valid && res.error) {
    response.details.instagramAccountId.error = res.error;
  }
  if (res.suggestion) {
    response.details.instagramAccountId.suggestion = res.suggestion;
  }
  if (res.valid) validCount++;
}

// --- 4. Calcular el Estado General y el Mensaje Principal ---
if (totalCount > 0) {
  if (validCount === totalCount) {
    response.overallStatus = 'success';
    response.success = true;
    response.message = 'Todos los IDs han sido verificados correctamente';
  } else if (validCount > 0) {
    response.overallStatus = 'partial';
    response.success = true; // Aún se considera un éxito de la operación
    response.message = 'Verificación parcial: algunos IDs requieren atención';
  } else {
    response.overallStatus = 'failed';
    response.success = false;
    response.message = 'Ninguno de los IDs proporcionados es válido';
  }
} else {
    response.message = 'No se proporcionaron IDs para verificar.';
}


// --- 5. Añadir error global de la API de Meta (si existe) ---
if (inputData.metaApiError) {
  response.metaApiError = inputData.metaApiError;
  response.success = false;
  response.overallStatus = 'failed';
  response.message = inputData.metaApiError.message || "Error de autenticación con Meta API";
}

// --- 6. Devolver el objeto JSON construido ---
return { json: response };

// El input ('items') es un array que contiene un solo objeto.
// Accedemos al array de templates que está en 'items[0].json.templates'.
const rawTemplateArray = items[0].json.templates;

// Verificamos si el array existe para evitar errores.
if (!rawTemplateArray || !Array.isArray(rawTemplateArray)) {
  // Si no hay templates, devolvemos una estructura vacía.
  return { json: { templates: [] } };
}

// Mapeamos sobre cada template en el array para transformarlo.
const transformedTemplates = rawTemplateArray.map(template => {
  return {
    id: template.id,
    templateName: template.templateName,
    description: template.description,
    flexible_spec: [
      {
        // El primer segmento contiene la lista original de intereses.
        interests: template.interests || []
      },
      {
        // El segundo segmento ahora usa los intereses de acotación si existen
        interests: template.acotados || []
      }
    ],
    createdAt: template.createdAt,
    // Asignamos createdAt a updatedAt como en el ejemplo anterior.
    updatedAt: template.createdAt
  };
});

// Devolvemos el resultado final envuelto en la estructura deseada,
// coincidiendo con el formato de respuesta de tu API.
return {
  json: {
    templates: transformedTemplates
  }
};

// 1. OBTENCIÓN Y NORMALIZACIÓN DE DATOS
const rawInput = $input.first().json.campaign_id;

let idList = [];

// Validación: Si es string, parseamos. Si es array, usamos directo.
if (typeof rawInput === 'string') {
  try {
    // Convertimos "[[\"123\"]]" a un array real [["123"]]
    const parsed = JSON.parse(rawInput);

    // Usamos .flat() para convertir [["123"]] en ["123"]
    // Esto es vital porque tu input tiene doble anidación
    idList = Array.isArray(parsed) ? parsed.flat() : [parsed];

  } catch (e) {
    // Si no es un JSON válido, asumimos que es un ID suelto
    idList = [rawInput];
  }
} else if (Array.isArray(rawInput)) {
  // Si ya llega como array, aplanamos por seguridad
  idList = rawInput.flat();
} else {
  // Fallback por si llega nulo o undefined
  idList = rawInput ? [rawInput] : [];
}

// 2. RETORNO ITERADO
return idList.map(id => {
  return {
    json: {
      id: String(id).trim() // Limpieza final del ID
    }
  };
});

